use std::collections::{BTreeMap, BTreeSet};

use crate::content::{Bytes, Chunk, Content, IdentRef, Token};
use crate::delta::{Delta, ObservedClass};
use crate::entity::{EntityRecord, Kind, SigKey};
use crate::error::{Error, Result};
use crate::ids::{ByteRange, EntityId, RelPath, resolve_spec};
use crate::lang::{Lang, Langs};
use crate::op::Intent;
use crate::snapshot::Snapshot;
use crate::store::Store;

use super::diff_impl::lang_for_ext;
use super::{
    classify_entity, env_from_snapshot_store, fill_self_methods_from_snapshot, ingest_file_prev,
    ingest_file_with_env, parse, render, render_entity,
};

pub fn lookup_name(snap: &Snapshot, name: &str) -> Result<EntityId> {
    let hits: Vec<_> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.name == name)
        .map(|(id, _)| *id)
        .collect();
    match hits.len() {
        1 => Ok(hits[0]),
        0 => Err(Error::NotFound(name.into())),
        _ => Err(Error::Other(format!("ambiguous name {name}"))),
    }
}

pub fn lookup(snap: &Snapshot, spec: &str) -> Result<EntityId> {
    if let Ok(id) = lookup_name(snap, spec) {
        return Ok(id);
    }
    match resolve_spec(snap.entities.keys().copied(), |id| id.matches_spec(spec)) {
        Ok(id) => Ok(id),
        Err(hits) if hits.is_empty() => Err(Error::NotFound(spec.into())),
        Err(_) => Err(Error::Other(format!("ambiguous entity {spec}"))),
    }
}

/// Attribute-only: referrers keep `Chunk::Name` holes. No rehash.
pub fn rename(store: &dyn Store, snap: &Snapshot, id: EntityId, new: &str) -> Result<Snapshot> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let has_decl = store
        .get_bytes_blob(rec.bytes)?
        .chunks()
        .iter()
        .any(|c| matches!(c, Chunk::Name(e) if *e == EntityId::SELF));
    if !has_decl {
        return Err(Error::Other(format!(
            "rename cannot rewrite {}; the declaration has no name spelling",
            rec.name
        )));
    }
    let mut next = snap.clone();
    next.rename(id, new)?;
    Ok(next)
}

pub fn relocate(snap: &Snapshot, store: &dyn Store, id: EntityId, file: RelPath, ordinal: u32) -> Result<Snapshot> {
    let from = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .file
        .clone();
    let mut next = snap.clone();
    // Render iterates `snapshot.files`, not entities. A path that never had a
    // FileRecord would swallow the item on disk even though the entity moved.
    next.ensure_file(file.clone());
    next.make_room_at_root(&file, ordinal, id);
    next.set_file(id, file.clone(), ordinal)?;
    normalize_root_separators(store, &mut next, &file)?;
    if from != file {
        normalize_root_separators(store, &mut next, &from)?;
    }
    Ok(next)
}

pub fn move_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: Option<u32>,
) -> Result<Snapshot> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    if let Some(p) = new_parent {
        if p == id || subtree(snap, id).contains(&p) {
            return Err(Error::Other("move would create a cycle".into()));
        }
        snap.entities.get(&p).ok_or(Error::NoSuchEntity(p))?;
    }
    let old_parent = rec.parent;
    let mut next = snap.clone();
    if let (None, Some(o)) = (new_parent, ordinal) {
        next.make_room_at_root(&rec.file, o, id);
    }
    next.reparent(id, new_parent, ordinal)?;
    if let Some(p) = new_parent {
        let file = next.entities[&p].file.clone();
        next.set_file(id, file, ordinal.unwrap_or(rec.ordinal))?;
    }
    if old_parent != new_parent {
        reindent_subtree(store, &mut next, id, new_parent)?;
    }
    if old_parent == new_parent {
        if let Some(p) = new_parent {
            let mut kids = child_ids_of(store, &next, p)?;
            kids.retain(|c| *c != id);
            let at = ordinal.unwrap_or(kids.len() as u32) as usize;
            kids.insert(at.min(kids.len()), id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
        if new_parent.is_none() {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
        return Ok(next);
    }
    if let Some(p) = old_parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    if let Some(p) = new_parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = ordinal.unwrap_or(kids.len() as u32) as usize;
        kids.insert(at.min(kids.len()), id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    reresolve_subtree(store, langs, &mut next, id)?;
    if old_parent.is_none() || new_parent.is_none() {
        let file = next.entities[&id].file.clone();
        normalize_root_separators(store, &mut next, &file)?;
        if rec.file != file {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
    }
    Ok(next)
}

pub fn extract_hoist(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: u32,
) -> Result<Snapshot> {
    move_def(store, langs, snap, id, new_parent, Some(ordinal))
}

/// Parse the destination file so inherited generics / outer locals match the
/// new parent, then copy the subtree's content and bytes back. Reorder under
/// the same parent does not call this — the env did not change.
fn reresolve_subtree(
    store: &dyn Store,
    langs: &Langs,
    snap: &mut Snapshot,
    id: EntityId,
) -> Result<()> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let rendered = render(snap, store, langs, false)?;
    let src = rendered
        .files
        .get(&rec.file)
        .ok_or_else(|| Error::Other(format!("re-resolve missing file {}", rec.file)))?;
    let env = env_from_snapshot_store(snap, store);
    let part = ingest_file_prev(
        src,
        rec.file.clone(),
        lang,
        store,
        snap.change,
        Some(snap),
        &env,
    )?;
    for eid in subtree(snap, id) {
        let (name, kind, parent) = {
            let rec = snap.entities.get(&eid).ok_or(Error::NoSuchEntity(eid))?;
            (rec.name.clone(), rec.kind, rec.parent)
        };
        let fresh = part
            .entities
            .get(&eid)
            .or_else(|| {
                part.entities
                    .values()
                    .find(|r| r.name == name && r.kind == kind && r.parent == parent)
            })
            .ok_or_else(|| Error::Other(format!("re-resolve lost {name}")))?;
        let content = fresh.content;
        let bytes = fresh.bytes;
        if let Some(dest) = snap.entities.get_mut(&eid) {
            dest.content = content;
            dest.bytes = bytes;
        }
    }
    Ok(())
}

pub fn delete(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Snapshot> {
    let tree = subtree(snap, id);
    let mut outside = Vec::new();
    for d in &tree {
        outside.extend(
            referrers(snap, store, *d)?
                .into_iter()
                .filter(|r| !tree.contains(r)),
        );
    }
    outside.sort();
    outside.dedup();
    if !outside.is_empty() {
        let named: Vec<String> = outside
            .iter()
            .take(5)
            .map(|r| match snap.entities.get(r) {
                Some(rec) => format!("{} ({}⟨{}⟩)", rec.name, rec.file, r.short()),
                None => format!("⟨{}⟩", r.short()),
            })
            .collect();
        let more = if outside.len() > 5 {
            format!(", and {} more", outside.len() - 5)
        } else {
            String::new()
        };
        return Err(Error::Other(format!(
            "delete refused: still referenced by {}{more}",
            named.join(", ")
        )));
    }
    let parent = snap.entities.get(&id).and_then(|r| r.parent);
    let mut next = snap.clone();
    for d in tree {
        next.entities.remove(&d);
    }
    if let Some(p) = parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    Ok(next)
}

pub fn inline(store: &dyn Store, langs: &Langs, snap: &Snapshot, id: EntityId) -> Result<Snapshot> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    // A `use` line that imports the callee names it too; it is not a call site, and
    // after the splice it would import something that no longer exists.
    let (imports, calls): (Vec<EntityId>, Vec<EntityId>) = name_use_sites(snap, store, id)?
        .into_iter()
        .partition(|s| snap.entities[s].kind == Kind::Opaque);
    if let Some(import) = imports.first() {
        let i = &snap.entities[import];
        return Err(Error::Other(format!(
            "inline refused: `{}` is imported by `{}` in {}; drop it from that import first",
            rec.name,
            i.name.lines().next().unwrap_or(&i.name),
            i.file
        )));
    }
    if calls.len() != 1 {
        return Err(Error::Other(format!(
            "inline requires a single use; found {}",
            calls.len()
        )));
    }
    let referrer = calls[0];
    if subtree(snap, referrer).contains(&id) {
        return Err(Error::Other(
            "inline cannot target an item still nested in the call site; extract first".into(),
        ));
    }
    let replacement = inlined_call_text(store, langs, snap, id, referrer)?;
    let (next, _) = edit_def(store, langs, snap, referrer, &replacement)?;
    delete(&next, store, id)
}

/// `Chunk::Name(id)` sites, including recursive uses inside `id` itself.
/// The declaration hole is `Name(SELF)`, not `Name(id)`.
fn name_use_sites(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut sites = Vec::new();
    for (oid, rec) in &snap.entities {
        let n = store
            .get_bytes_blob(rec.bytes)?
            .chunks()
            .iter()
            .filter(|c| chunk_names(c, id))
            .count();
        for _ in 0..n {
            sites.push(*oid);
        }
    }
    Ok(sites)
}

fn chunk_names(chunk: &Chunk, want: EntityId) -> bool {
    match chunk {
        Chunk::Name(e) => *e == want,
        Chunk::ShorthandName { id, .. } => *id == want,
        _ => false,
    }
}

fn inlined_call_text(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    referrer: EntityId,
) -> Result<Vec<u8>> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let (callee, _) = render_entity(snap, store, id, false)?;
    let (params, body) = callee_params_and_body(lang, &callee)?;
    let (caller, map) = render_entity(snap, store, referrer, true)?;
    let ranges: Vec<ByteRange> = map
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .filter_map(|(r, ident)| match ident {
            IdentRef::Entity(e) if *e == id => Some(*r),
            _ => None,
        })
        .collect();
    match ranges.as_slice() {
        [range] => {
            let name_end = range.end as usize;
            if name_end > caller.len() || (range.start as usize) > name_end {
                return Err(Error::Other("inline call range is out of bounds".into()));
            }
            let (call_end, args) = extend_call(&caller, name_end)?;
            if args.len() != params.len() {
                return Err(Error::Other(format!(
                    "inline expected {} argument(s), found {}",
                    params.len(),
                    args.len()
                )));
            }
            let mut block = bind_and_body(&params, &args, &body);
            if rust_postfix(&caller, call_end) {
                if lang.name() != "rust" {
                    return Err(Error::Other(
                        "inline of an expression-position call is only supported in rust".into(),
                    ));
                }
                block = format!("({block})");
            }
            let start = range.start as usize;
            let mut out = Vec::with_capacity(caller.len() + block.len());
            out.extend_from_slice(&caller[..start]);
            out.extend_from_slice(block.as_bytes());
            out.extend_from_slice(&caller[call_end..]);
            Ok(out)
        }
        _ => Err(Error::Other(format!(
            "inline needs one call name in the unique user; found {}",
            ranges.len()
        ))),
    }
}

fn callee_params_and_body(lang: &dyn Lang, src: &[u8]) -> Result<(Vec<String>, String)> {
    let tree = parse(src, lang)?;
    let item = entity_item_node(tree.root_node(), lang)
        .ok_or_else(|| Error::Other("inline target does not parse as a language item".into()))?;
    let rule = lang
        .entity_kinds()
        .iter()
        .find(|r| r.node_kind == item.kind())
        .ok_or_else(|| Error::Other("inline target is not a language item".into()))?;
    let body_field = rule.body_field.ok_or_else(|| {
        Error::Other("inline needs an item with a body (not a type or signature)".into())
    })?;
    let body = item
        .child_by_field_name(body_field)
        .ok_or_else(|| Error::Other("inline target has no body".into()))?;
    let params = match item.child_by_field_name("parameters") {
        Some(n) => param_names(n, src)?,
        None => Vec::new(),
    };
    Ok((params, node_src(src, body)))
}

fn entity_item_node<'a>(
    node: tree_sitter::Node<'a>,
    lang: &dyn Lang,
) -> Option<tree_sitter::Node<'a>> {
    if lang
        .entity_kinds()
        .iter()
        .any(|r| r.node_kind == node.kind())
    {
        return Some(node);
    }
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        if let Some(hit) = entity_item_node(ch, lang) {
            return Some(hit);
        }
    }
    None
}

fn param_names(params: tree_sitter::Node<'_>, src: &[u8]) -> Result<Vec<String>> {
    let mut names = Vec::new();
    let mut c = params.walk();
    for ch in params.named_children(&mut c) {
        match ch.kind() {
            "self_parameter" => {
                return Err(Error::Other(
                    "inline of a method (self) is not supported".into(),
                ));
            }
            "identifier" => names.push(node_src(src, ch)),
            "parameter" | "required_parameter" | "optional_parameter" | "rest_parameter"
            | "assignment_pattern" => {
                let pat = ch
                    .child_by_field_name("pattern")
                    .or_else(|| ch.child_by_field_name("name"))
                    .unwrap_or(ch);
                match simple_pat_name(pat, src) {
                    Some(n) => names.push(n),
                    None => {
                        return Err(Error::Other(
                            "inline needs simple identifier parameters".into(),
                        ));
                    }
                }
            }
            _ => {}
        }
    }
    Ok(names)
}

fn simple_pat_name(node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String> {
    match node.kind() {
        "identifier" => Some(node_src(src, node)),
        "mut_pattern" => {
            let mut c = node.walk();
            node.named_children(&mut c)
                .find(|ch| ch.kind() == "identifier")
                .map(|id| node_src(src, id))
        }
        _ => None,
    }
}

fn node_src(src: &[u8], n: tree_sitter::Node<'_>) -> String {
    let a = n.start_byte().min(src.len());
    let b = n.end_byte().min(src.len()).max(a);
    String::from_utf8_lossy(&src[a..b]).into_owned()
}

fn extend_call(src: &[u8], name_end: usize) -> Result<(usize, Vec<String>)> {
    let mut i = name_end;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    if i >= src.len() || src[i] != b'(' {
        return Err(Error::Other("inline needs a call site".into()));
    }
    let close = matching_paren(src, i)?;
    Ok((close + 1, split_args(&src[i + 1..close])))
}

fn matching_paren(src: &[u8], open: usize) -> Result<usize> {
    let mut i = open;
    let mut depth = 0i32;
    while i < src.len() {
        let b = src[i];
        if b == b'/' && i + 1 < src.len() {
            if src[i + 1] == b'/' {
                i += 2;
                while i < src.len() && src[i] != b'\n' {
                    i += 1;
                }
                continue;
            }
            if src[i + 1] == b'*' {
                i += 2;
                while i + 1 < src.len() && !(src[i] == b'*' && src[i + 1] == b'/') {
                    i += 1;
                }
                i = i.saturating_add(2);
                continue;
            }
        }
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < src.len() {
                if src[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if src[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        if b == b'(' {
            depth += 1;
        } else if b == b')' {
            depth -= 1;
            if depth == 0 {
                return Ok(i);
            }
        }
        i += 1;
    }
    Err(Error::Other("inline call is unclosed".into()))
}

fn split_args(inner: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut i = 0usize;
    while i < inner.len() {
        let b = inner[i];
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < inner.len() {
                if inner[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if inner[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        match b {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.saturating_sub(1),
            b',' if depth == 0 => {
                push_arg(&mut out, &inner[start..i]);
                start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    push_arg(&mut out, &inner[start..]);
    out
}

fn push_arg(out: &mut Vec<String>, piece: &[u8]) {
    let s = String::from_utf8_lossy(piece).trim().to_string();
    if !s.is_empty() {
        out.push(s);
    }
}

fn bind_and_body(params: &[String], args: &[String], body: &str) -> String {
    if params.is_empty() {
        return body.to_string();
    }
    let mut s = String::from("{\n");
    for (p, a) in params.iter().zip(args) {
        s.push_str("    let ");
        s.push_str(p);
        s.push_str(" = ");
        s.push_str(a);
        s.push_str(";\n");
    }
    s.push_str(body);
    if !body.ends_with('\n') {
        s.push('\n');
    }
    s.push('}');
    s
}

fn rust_postfix(src: &[u8], after_call: usize) -> bool {
    let mut i = after_call;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    i < src.len() && matches!(src[i], b'?' | b'.')
}

pub fn edit_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<(Snapshot, ObservedClass)> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let definition = item_text(store, snap, id, definition)?;
    let (root_old, part) = ingest_item_tree(
        "edit-def",
        store,
        snap,
        &rec.file,
        lang,
        rec.parent,
        &definition,
    )?;
    let mapped = remap_tree(store, part.entities, root_old, id, Some(snap))?;
    let new_rec = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("edit-def lost the root item".into()))?;
    if new_rec.name != rec.name {
        return Err(Error::Other(format!(
            "edit-def cannot rename {} to {}; use svc rename",
            rec.name, new_rec.name
        )));
    }
    if new_rec.kind != rec.kind {
        return Err(Error::Other(format!(
            "edit-def cannot change {} from {:?} to {:?}; delete and add-def instead",
            rec.name, rec.kind, new_rec.kind
        )));
    }
    let new_content = new_rec.content;
    let new_bytes = new_rec.bytes;
    let mut next = snap.clone();
    for cid in subtree(snap, id) {
        if cid != id {
            next.entities.remove(&cid);
        }
    }
    if let Some(dest) = next.entities.get_mut(&id) {
        dest.content = new_content;
        dest.bytes = new_bytes;
    }
    for (cid, mut child) in mapped {
        if cid == id {
            continue;
        }
        child.file = rec.file.clone();
        next.insert(cid, child)?;
    }
    let class = classify_entity(store, snap, &next, id)?;
    Ok((next, class))
}

pub fn add_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    ordinal: u32,
    definition: &[u8],
    intent: Intent,
) -> Result<Snapshot> {
    add_def_at(
        store, langs, snap, id, parent, None, ordinal, definition, intent,
    )
}

/// Parent's file, else the first tracked source file. An explicit `file` wins.
pub fn resolve_add_def_file(
    snap: &Snapshot,
    langs: &Langs,
    parent: Option<EntityId>,
    file: Option<RelPath>,
) -> Result<RelPath> {
    if let Some(file) = file {
        return Ok(file);
    }
    match parent {
        Some(p) => Ok(snap
            .entities
            .get(&p)
            .ok_or(Error::NoSuchEntity(p))?
            .file
            .clone()),
        None => Ok(snap
            .files
            .keys()
            .find(|p| langs.for_path(p).is_some())
            .cloned()
            .ok_or_else(|| Error::Other("no tracked source file to add into".into()))?),
    }
}

pub fn add_def_at(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    file: Option<RelPath>,
    ordinal: u32,
    definition: &[u8],
    _intent: Intent,
) -> Result<Snapshot> {
    let file = resolve_add_def_file(snap, langs, parent, file)?;
    let lang = langs
        .for_path(&file)
        .ok_or_else(|| Error::NoLanguage(file.clone()))?;
    let indent = parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    let definition = add_def_text(parent, &indent, definition);
    let (root_old, part) =
        ingest_item_tree("add-def", store, snap, &file, lang, parent, &definition)?;
    let mapped = remap_tree(store, part.entities, root_old, id, None)?;
    let mut next = snap.clone();
    next.ensure_file(file.clone());
    let mut root = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("add-def lost the root item".into()))?;
    root.parent = parent;
    root.file = file.clone();
    root.ordinal = ordinal;
    if parent.is_none() {
        next.make_room_at_root(&file, ordinal, id);
    }
    next.insert(id, root)?;
    for (cid, mut rec) in mapped {
        if cid == id {
            continue;
        }
        rec.file = file.clone();
        next.insert(cid, rec)?;
    }
    if let Some(p) = parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = (ordinal as usize).min(kids.len());
        kids.insert(at, id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    Ok(next)
}

pub fn classify_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<ObservedClass> {
    let (_, class) = edit_def(store, langs, snap, id, definition)?;
    Ok(class)
}

pub fn show(store: &dyn Store, snap: &Snapshot, id: EntityId) -> Result<String> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let content = store.get_content(rec.content)?;
    Ok(format_tokens(snap, &content.tokens, &rec.name))
}

pub fn format_tokens(snap: &Snapshot, tokens: &[Token], self_name: &str) -> String {
    let mut out = String::new();
    for t in tokens {
        match t {
            Token::Punct(p) | Token::Kw(p) | Token::Lit(p) => out.push_str(p),
            Token::Binder(s, _) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Local(s, _)) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Free(n)) => out.push_str(n),
            Token::Ident(IdentRef::Entity(eid)) if *eid == EntityId::SELF => {
                out.push_str(self_name)
            }
            Token::Ident(IdentRef::Entity(eid)) | Token::Child(eid) => {
                let name = snap
                    .entities
                    .get(eid)
                    .map(|e| e.name.as_str())
                    .unwrap_or("?");
                out.push_str(&format!("#{name}⟨{}⟩", eid.short()));
            }
        }
        out.push(' ');
    }
    out
}

/// Layout: alpha/docs-only edits, commutative relocations, and file deltas of source
/// files (their entities are counted on their own; a tail is trivia, or whitespace).
/// Semantic: everything else, including any change to a file svc has no language for.
pub fn status_report(store: &dyn Store, prev: &Snapshot, next: &Snapshot) -> Result<StatusReport> {
    let deltas = super::diff(store, prev, next)?;
    let is_source = |p: &RelPath| lang_for_ext(p.extension()).is_some();
    let mut layout = 0usize;
    let mut semantic = 0usize;
    let mut rebound = 0usize;
    for d in &deltas {
        match d {
            Delta::Rebound(_, _) => rebound += 1,
            Delta::Edited(_, ObservedClass::Alpha | ObservedClass::DocsOnly)
            | Delta::Relocated { .. } => layout += 1,
            Delta::FileAdded(p) | Delta::FileRemoved(p) if is_source(p) => layout += 1,
            Delta::FileTail { path, whitespace_only } if *whitespace_only || is_source(path) => {
                layout += 1
            }
            _ => semantic += 1,
        }
    }
    Ok(StatusReport {
        entities: next.entities.len(),
        deltas,
        layout,
        semantic,
        rebound,
    })
}

#[derive(Clone, Debug)]
pub struct StatusReport {
    pub entities: usize,
    pub deltas: Vec<Delta>,
    pub layout: usize,
    pub semantic: usize,
    /// Same bytes, different content — named, not counted as an edit.
    pub rebound: usize,
}

impl StatusReport {
    pub fn summary(&self) -> String {
        let rebound = if self.rebound == 0 {
            String::new()
        } else if self.rebound == 1 {
            "; 1 rebound, text unchanged".into()
        } else {
            format!("; {} rebound, text unchanged", self.rebound)
        };
        if self.deltas.is_empty() {
            format!("{} entities, 0 changes", self.entities)
        } else if self.semantic == 0 && self.layout == 0 {
            format!(
                "{} rebound, text unchanged ({} entities)",
                self.rebound, self.entities
            )
        } else if self.semantic == 0 {
            format!("no semantic changes; {} layout{rebound}", self.layout)
        } else {
            format!(
                "{} semantic; {} layout ({} entities){rebound}",
                self.semantic, self.layout, self.entities
            )
        }
    }
}

/// Entities whose content or bytes *name* `id`. Child holes are containment,
/// not uses — counting them made every nested delete refuse.
pub fn referrers(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut out = Vec::new();
    for (oid, rec) in &snap.entities {
        if *oid == id {
            continue;
        }
        let in_content = store
            .get_content(rec.content)?
            .tokens
            .iter()
            .any(|t| match t {
                Token::Ident(IdentRef::Entity(e)) => *e == id,
                _ => false,
            });
        let in_bytes = || -> Result<bool> {
            Ok(store
                .get_bytes_blob(rec.bytes)?
                .chunks()
                .iter()
                .any(|c| chunk_names(c, id)))
        };
        if in_content || in_bytes()? {
            out.push(*oid);
        }
    }
    Ok(out)
}

fn child_ids_in_chunks(chunks: &[Chunk]) -> Vec<EntityId> {
    chunks
        .iter()
        .filter_map(|c| match c {
            Chunk::Child(id) => Some(*id),
            _ => None,
        })
        .collect()
}

fn child_ids_of(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Result<Vec<EntityId>> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?;
    Ok(child_ids_in_chunks(
        store.get_bytes_blob(rec.bytes)?.chunks(),
    ))
}

fn apply_child_holes(
    store: &dyn Store,
    snap: &mut Snapshot,
    parent: EntityId,
    want: &[EntityId],
) -> Result<()> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?
        .clone();
    let bytes = store.get_bytes_blob(rec.bytes)?;
    let content = store.get_content(rec.content)?;
    let new_bytes = rewrite_bytes_children(&bytes, want)?;
    let new_content = Content {
        tokens: rewrite_content_children(content.tokens, want),
    };
    let bytes_id = store.put_bytes_blob(&new_bytes)?;
    let content_id = store.put_content(&new_content)?;
    let rec = snap.entities.get_mut(&parent).unwrap();
    rec.bytes = bytes_id;
    rec.content = content_id;
    Ok(())
}

fn rewrite_bytes_children(bytes: &Bytes, want: &[EntityId]) -> Result<Bytes> {
    let have = child_ids_in_chunks(bytes.chunks());
    if have == want {
        return Ok(Bytes::new(
            bytes.src().to_vec(),
            bytes.chunks().to_vec(),
            bytes.local_ranges().to_vec(),
        )?);
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut src = bytes.src().to_vec();
    let mut chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .cloned()
        .filter(|c| match c {
            Chunk::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if child_ids_in_chunks(&chunks).contains(id) {
            continue;
        }
        chunks = insert_child_chunk(&mut src, chunks, *id, i);
    }
    let have = child_ids_in_chunks(&chunks);
    if have != want {
        let mut iter = want.iter();
        for c in &mut chunks {
            if let Chunk::Child(id) = c
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    Bytes::new(src, chunks, bytes.local_ranges().to_vec())
}

fn insert_child_chunk(
    src: &mut Vec<u8>,
    mut chunks: Vec<Chunk>,
    id: EntityId,
    ordinal: usize,
) -> Vec<Chunk> {
    let positions: Vec<usize> = chunks
        .iter()
        .enumerate()
        .filter_map(|(i, c)| matches!(c, Chunk::Child(_)).then_some(i))
        .collect();
    let insert_at = if ordinal < positions.len() {
        positions[ordinal]
    } else if let Some(&last) = positions.last() {
        last + 1
    } else {
        split_close_brace(src, &mut chunks)
    };
    // A member's bytes end at its last token; whatever follows must begin on a new
    // line. The next sibling carries its own leading newline, and so does the parent's
    // closing text in every rendered file — only a bare `}` (split_close_brace) or a
    // literal that starts mid-line needs one added here.
    let next_starts_on_new_line = match chunks.get(insert_at) {
        Some(Chunk::Child(_)) => true,
        Some(Chunk::Literal(r)) => src.get(r.start as usize) == Some(&b'\n'),
        Some(Chunk::Name(_) | Chunk::ShorthandName { .. }) | None => false,
    };
    chunks.insert(insert_at, Chunk::Child(id));
    if !next_starts_on_new_line {
        let extra_start = src.len() as u32;
        src.extend_from_slice(b"\n");
        let extra = ByteRange {
            start: extra_start,
            end: src.len() as u32,
        };
        chunks.insert(insert_at + 1, Chunk::Literal(extra));
    }
    chunks
}

fn split_close_brace(src: &[u8], chunks: &mut Vec<Chunk>) -> usize {
    for i in (0..chunks.len()).rev() {
        let Chunk::Literal(r) = chunks[i] else {
            continue;
        };
        let slice = &src[r.start as usize..r.end as usize];
        let Some(rel) = slice.iter().rposition(|&b| b == b'}') else {
            continue;
        };
        let brace = r.start + rel as u32;
        chunks.remove(i);
        let mut at = i;
        if brace > r.start {
            chunks.insert(
                at,
                Chunk::Literal(ByteRange {
                    start: r.start,
                    end: brace,
                }),
            );
            at += 1;
        }
        chunks.insert(
            at,
            Chunk::Literal(ByteRange {
                start: brace,
                end: r.end,
            }),
        );
        return at;
    }
    chunks.len()
}

fn rewrite_content_children(tokens: Vec<Token>, want: &[EntityId]) -> Vec<Token> {
    let content_kids = |tokens: &[Token]| -> Vec<EntityId> {
        tokens
            .iter()
            .filter_map(|t| match t {
                Token::Child(id) => Some(*id),
                _ => None,
            })
            .collect()
    };
    if content_kids(&tokens) == want {
        return tokens;
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut tokens: Vec<Token> = tokens
        .into_iter()
        .filter(|t| match t {
            Token::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if content_kids(&tokens).contains(id) {
            continue;
        }
        let positions: Vec<usize> = tokens
            .iter()
            .enumerate()
            .filter_map(|(j, t)| matches!(t, Token::Child(_)).then_some(j))
            .collect();
        let at = if i < positions.len() {
            positions[i]
        } else if let Some(&last) = positions.last() {
            last + 1
        } else {
            tokens
                .iter()
                .rposition(|t| matches!(t, Token::Punct(p) if p.as_ref() == "}"))
                .unwrap_or(tokens.len())
        };
        tokens.insert(at, Token::Child(*id));
    }
    if content_kids(&tokens) != want {
        let mut iter = want.iter();
        for t in &mut tokens {
            if let Token::Child(id) = t
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    tokens
}

fn subtree(snap: &Snapshot, id: EntityId) -> BTreeSet<EntityId> {
    let mut out = BTreeSet::from([id]);
    let mut grow = true;
    while grow {
        grow = false;
        for (cid, rec) in &snap.entities {
            if let Some(p) = rec.parent
                && out.contains(&p)
                && out.insert(*cid)
            {
                grow = true;
            }
        }
    }
    out
}

pub fn commit_snapshot(store: &dyn Store, snap: &Snapshot) -> Result<crate::ids::SnapshotId> {
    let id = store.put_snapshot(snap)?;
    store.set_root(id)?;
    store.set_head(snap.change, id)?;
    Ok(id)
}

pub fn rust_langs() -> Langs {
    Langs::new(vec![Box::new(crate::RustLang)])
}

/// Same nested-child keep as `edit_def`. Returns the new snapshot plus the
/// edited root's hashes so O3 can assert callee holes without walking entities.
pub fn redefine(
    store: &dyn Store,
    langs: &Langs,
    snapshot: &Snapshot,
    id: EntityId,
    text: &[u8],
) -> Result<(Snapshot, crate::ids::ContentId, crate::ids::BytesId)> {
    let (next, _) = edit_def(store, langs, snapshot, id, text)?;
    let rec = next.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let hashes = (rec.content, rec.bytes);
    Ok((next, hashes.0, hashes.1))
}

/// The one item a verb body must be: parses without error nodes, exactly one root
/// entity. Ingest itself is lenient (a checked-in file may be mid-edit); the typed
/// write path is not.
/// Parse and ingest one definition. Under a parent whose members do not parse on their
/// own (a JS class), the text is wrapped in the language's member shell and the member,
/// not the shell, is returned as the root.
fn ingest_item_tree(
    verb: &str,
    store: &dyn Store,
    snap: &Snapshot,
    file: &RelPath,
    lang: &dyn crate::lang::Lang,
    parent: Option<EntityId>,
    text: &[u8],
) -> Result<(EntityId, Snapshot)> {
    let parent_kind = parent.and_then(|p| snap.entities.get(&p)).map(|r| r.kind);
    let shell = parent_kind.and_then(|k| lang.member_shell(k));
    let wrapped: Vec<u8> = match shell {
        Some((open, close)) => [open.as_bytes(), text, close.as_bytes()].concat(),
        None => text.to_vec(),
    };
    if super::parse(&wrapped, lang)?.root_node().has_error() {
        return Err(Error::Parse(format!(
            "{verb} definition does not parse as {}",
            lang.name()
        )));
    }
    let mut env = env_from_snapshot_store(snap, store);
    fill_self_methods_from_snapshot(&mut env, snap, parent);
    let mut part = ingest_file_with_env(&wrapped, file.clone(), lang, store, snap.change, &env)?;
    let roots: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent.is_none())
        .map(|(id, _)| *id)
        .collect();
    let [root] = roots.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must parse to exactly one item"
        )));
    };
    let root = *root;
    if shell.is_none() {
        return Ok((root, part));
    }
    let members: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(root))
        .map(|(id, _)| *id)
        .collect();
    let [member] = members.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must be exactly one member"
        )));
    };
    let member = *member;
    part.entities.remove(&root);
    part.entities.get_mut(&member).unwrap().parent = None;
    Ok((member, part))
}

fn derived_id(parent: EntityId, rec: &EntityRecord) -> EntityId {
    let mut h = blake3::Hasher::new();
    h.update(parent.0.as_bytes());
    h.update(&[0]);
    h.update(format!("{:?}", rec.kind).as_bytes());
    h.update(&[0]);
    h.update(rec.name.as_bytes());
    h.update(&[0]);
    h.update(&rec.ordinal.to_le_bytes());
    let hash = h.finalize();
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&hash.as_bytes()[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x80;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    EntityId(uuid::Uuid::from_bytes(bytes))
}

fn remap_tree(
    store: &dyn Store,
    tree: BTreeMap<EntityId, EntityRecord>,
    root_old: EntityId,
    root_new: EntityId,
    prev: Option<&Snapshot>,
) -> Result<BTreeMap<EntityId, EntityRecord>> {
    let mut id_map = BTreeMap::new();
    id_map.insert(root_old, root_new);
    let mut taken = BTreeSet::from([root_new]);
    let mut queue = vec![root_old];
    while let Some(old) = queue.pop() {
        let parent_new = id_map[&old];
        let mut kids: Vec<(EntityId, EntityRecord)> = tree
            .iter()
            .filter(|(_, r)| r.parent == Some(old))
            .map(|(i, r)| (*i, r.clone()))
            .collect();
        kids.sort_by_key(|(_, r)| r.ordinal);
        for (old_id, rec) in kids {
            let new_id = match prev {
                Some(prev) => {
                    let key = SigKey::new(Some(parent_new), &rec.file, rec.kind, rec.name.clone());
                    prev.entities
                        .iter()
                        .find_map(|(pid, r)| {
                            (!taken.contains(pid) && r.sig_key() == key).then_some(*pid)
                        })
                        .unwrap_or_else(|| derived_id(parent_new, &rec))
                }
                None => derived_id(parent_new, &rec),
            };
            taken.insert(new_id);
            id_map.insert(old_id, new_id);
            queue.push(old_id);
        }
    }
    let mut out = BTreeMap::new();
    for (old, rec) in &tree {
        let new_id = *id_map.get(old).unwrap_or(old);
        let mut rec = rec.clone();
        rec.parent = rec.parent.map(|p| *id_map.get(&p).unwrap_or(&p));
        let bytes = remap_bytes(&store.get_bytes_blob(rec.bytes)?, &id_map)?;
        let content = Content {
            tokens: remap_tokens(store.get_content(rec.content)?.tokens, &id_map),
        };
        rec.bytes = store.put_bytes_blob(&bytes)?;
        rec.content = store.put_content(&content)?;
        out.insert(new_id, rec);
    }
    Ok(out)
}

fn remap_id(id: EntityId, map: &BTreeMap<EntityId, EntityId>) -> EntityId {
    if id == EntityId::SELF {
        id
    } else {
        *map.get(&id).unwrap_or(&id)
    }
}

fn remap_bytes(bytes: &Bytes, map: &BTreeMap<EntityId, EntityId>) -> Result<Bytes> {
    let chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .map(|c| match c {
            Chunk::Child(id) => Chunk::Child(remap_id(*id, map)),
            Chunk::Name(id) => Chunk::Name(remap_id(*id, map)),
            Chunk::ShorthandName { id, field } => Chunk::ShorthandName {
                id: remap_id(*id, map),
                field: field.clone(),
            },
            other => other.clone(),
        })
        .collect();
    let locals: Vec<(ByteRange, IdentRef)> = bytes
        .local_ranges()
        .iter()
        .map(|(r, ident)| {
            let ident = match ident {
                IdentRef::Entity(id) => IdentRef::Entity(remap_id(*id, map)),
                other => other.clone(),
            };
            (*r, ident)
        })
        .collect();
    Bytes::new(bytes.src().to_vec(), chunks, locals)
}

fn remap_tokens(tokens: Vec<Token>, map: &BTreeMap<EntityId, EntityId>) -> Vec<Token> {
    tokens
        .into_iter()
        .map(|t| match t {
            Token::Child(id) => Token::Child(remap_id(id, map)),
            Token::Ident(IdentRef::Entity(id)) => Token::Ident(IdentRef::Entity(remap_id(id, map))),
            other => other,
        })
        .collect()
}

/// Keep the entity's leading trivia (blank lines / docs / attributes attached
/// by extent) and tolerate a missing trailing newline.
fn item_text(store: &dyn Store, snap: &Snapshot, id: EntityId, text: &[u8]) -> Result<Vec<u8>> {
    let (old, _) = super::render_entity(snap, store, id, false)?;
    let old_lead = leading_trivia_len(&old);
    let new_ws = text.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let new_lead = leading_trivia_len(text);
    let mut out = Vec::new();
    // A definition that starts at the item (`fn f`, `isValid()`) must not wipe
    // `///` / `#[attr]` that extent glued onto this entity.
    if new_lead == new_ws && old_lead > 0 {
        out.extend_from_slice(&old[..old_lead]);
        let rest = {
            let n = text.iter().take_while(|b| b.is_ascii_whitespace()).count();
            &text[n..]
        };
        out.extend_from_slice(rest);
    } else {
        out.extend_from_slice(text);
    }
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    Ok(out)
}

/// Whitespace, `//`/`///` line comments, `/* */` blocks, and `#[]` / `#![]`
/// attributes. Stops at the item keyword (`fn`, `pub`, `isValid`, …).
fn leading_trivia_len(src: &[u8]) -> usize {
    let mut i = 0;
    loop {
        while i < src.len() && src[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= src.len() {
            return i;
        }
        if src[i] == b'/' && src.get(i + 1) == Some(&b'/') {
            while i < src.len() && src[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        if src[i] == b'/' && src.get(i + 1) == Some(&b'*') {
            i += 2;
            while i + 1 < src.len() && !(src[i] == b'*' && src[i + 1] == b'/') {
                i += 1;
            }
            i = i.saturating_add(2).min(src.len());
            continue;
        }
        if src[i] == b'#' {
            let mut j = i + 1;
            if src.get(j) == Some(&b'!') {
                j += 1;
            }
            if src.get(j) == Some(&b'[') {
                j += 1;
                let mut depth = 1usize;
                while j < src.len() && depth > 0 {
                    match src[j] {
                        b'[' => depth += 1,
                        b']' => depth -= 1,
                        _ => {}
                    }
                    j += 1;
                }
                i = j;
                continue;
            }
        }
        return i;
    }
}

/// Re-indent `id` and everything nested in it from the level it had to the level of its
/// new parent (`None` = column 0), by the first code line's leading whitespace.
fn reindent_subtree(
    store: &dyn Store,
    snap: &mut Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
) -> Result<()> {
    let (rendered, _) = render_entity(snap, store, id, false)?;
    let lead = rendered.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let line_start = rendered[..lead].iter().rposition(|b| *b == b'\n').map_or(0, |p| p + 1);
    let from = rendered[line_start..lead].to_vec();
    let to = new_parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    if from == to {
        return Ok(());
    }
    for eid in subtree(snap, id) {
        let rec = &snap.entities[&eid];
        let bytes = store.get_bytes_blob(rec.bytes)?.reindent(&from, &to)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        snap.entities.get_mut(&eid).unwrap().bytes = bytes_id;
    }
    Ok(())
}

/// After roots of `file` were reordered: the first root starts at column 0 with no blank
/// line above it, every later root starts on a fresh line with one blank line before it —
/// unless it already begins with a newline, in which case its own trivia is kept. The
/// separator between two items lives in the second one's leading text, so an item moved
/// to or from the front would otherwise render glued (`}fn`) or leave a blank first line.
fn normalize_root_separators(store: &dyn Store, snap: &mut Snapshot, file: &RelPath) -> Result<()> {
    for (i, id) in snap.file_roots(file).into_iter().enumerate() {
        let rec = &snap.entities[&id];
        let bytes = store.get_bytes_blob(rec.bytes)?;
        let lead = bytes
            .chunks()
            .first()
            .and_then(|c| match c {
                Chunk::Literal(r) => Some(
                    bytes.src()[r.start as usize..r.end as usize]
                        .iter()
                        .take_while(|b| **b == b'\n')
                        .count(),
                ),
                _ => None,
            });
        let want = match (i, lead) {
            (0, Some(l)) if l > 0 => 0,
            (_, Some(0)) if i > 0 => 2,
            _ => continue,
        };
        let fixed = bytes.with_leading_newlines(want)?;
        let bytes_id = store.put_bytes_blob(&fixed)?;
        snap.entities.get_mut(&id).unwrap().bytes = bytes_id;
    }
    Ok(())
}

/// Indentation of `parent`'s existing members (the whitespace after the last newline
/// before the first member's text); four spaces when it has none yet.
fn sibling_indent(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Vec<u8> {
    let first = snap
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(parent))
        .min_by_key(|(_, r)| r.ordinal)
        .map(|(id, _)| *id);
    let indent = first
        .and_then(|id| render_entity(snap, store, id, false).ok())
        .and_then(|(bytes, _)| {
            let lead = bytes.iter().take_while(|b| b.is_ascii_whitespace()).count();
            let last_nl = bytes[..lead].iter().rposition(|b| *b == b'\n')?;
            Some(bytes[last_nl + 1..lead].to_vec())
        });
    indent
        .filter(|i| !i.is_empty())
        .unwrap_or_else(|| b"    ".to_vec())
}

/// A new item needs a blank line before it or render glues `}fn` / `;fn`. Nested items
/// (an impl method, a class member) are also indented one level when the body an
/// agent passes is written at column 0; a body that arrives indented is kept as is.
/// Only text that begins with its own newline is taken as already laid out.
fn add_def_text(parent: Option<EntityId>, indent: &[u8], text: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let laid_out = text.first() == Some(&b'\n');
    let indented = text.first().is_some_and(|b| *b == b' ' || *b == b'\t');
    if !laid_out {
        out.extend_from_slice(b"\n\n");
    }
    if parent.is_some() && !laid_out && !indented {
        for (i, line) in text.split(|b| *b == b'\n').enumerate() {
            if i > 0 {
                out.push(b'\n');
            }
            if !line.is_empty() {
                out.extend_from_slice(indent);
                out.extend_from_slice(line);
            }
        }
    } else {
        out.extend_from_slice(text);
    }
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    out
}

crates/svc-core/src/lang.rs.Text:
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use crate::content::Namespace;
use crate::entity::Kind;
use crate::ids::{ByteRange, EntityId, RelPath};

#[derive(Clone, Debug, Default)]
pub struct Env {
    pub names: Arc<HashMap<(String, Namespace), EntityId>>,
    /// File-root and nested defs keyed by the file they live in. A same-file
    /// `fn hex32` beats a same-named item in another crate when resolving.
    pub by_file: Arc<HashMap<RelPath, HashMap<(String, Namespace), EntityId>>>,
    /// Same-named items in `crates/<pkg>/**` share this map. File wins, then a
    /// name unique in the crate, then a name unique in the repo; collisions are Free.
    pub by_crate: Arc<HashMap<String, HashMap<(String, Namespace), EntityId>>>,
    /// Crate-level names that appear in more than one file. A third file must not
    /// bind last-wins (DOGFOOD: two file-level items with one name in one crate).
    pub crate_ambiguous: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Repo-wide names that appear under more than one definition.
    pub names_ambiguous: Arc<HashSet<(String, Namespace)>>,
    /// Occupants that own this (name, ns) as their primary namespace (`fn` in
    /// Value, not `struct` which also sits in Value as a constructor).
    pub primary: Arc<HashSet<(String, Namespace)>>,
    /// Per-crate primary occupants; same rule as [`Self::primary`].
    pub crate_primary: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Inherent methods and associated consts of the impl/class this item is
    /// being resolved in. `self.foo()` / `Self::foo` / `Self::N` / `this.foo()`
    /// look here, not in `names` (a free `fn foo` is a different target).
    pub self_methods: HashMap<String, EntityId>,
    /// Items nested in the function (or JS function/method) being resolved —
    /// `fn f() { fn g() {} g(); }`. They are not in [`Self::by_file`]: a sibling
    /// `fn h() { g(); }` must not bind to `f`'s helper, and a nested `fn parse`
    /// must not make a file-level `parse` in the same crate look ambiguous.
    pub nested_items: HashMap<(String, Namespace), EntityId>,
    /// When set, [`Self::lookup`] prefers [`Self::by_file`] for this path.
    pub current_file: Option<RelPath>,
    /// Inside `mod inner { … }`, bare names are the module's own items only.
    /// `crate::` still uses [`Self::lookup_module`].
    pub in_nested_mod: bool,
    /// Parent-mod maps for `super::` / `super::super::` / … Index 0 is one
    /// `super` (the parent of the enclosing mod). Past the last nested mod,
    /// [`Self::lookup_super`] falls through to [`Self::lookup_module`].
    pub super_stack: Vec<HashMap<(String, Namespace), EntityId>>,
    /// Children of each `mod` entity, for `crate::outer::parse` / `super::inner::f`.
    pub mod_items: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// Enclosing `mod` entity, for `self::inner::f`.
    pub self_mod: Option<EntityId>,
    /// File loaded by `mod foo;` → that `mod` entity. Items in the file are
    /// inside the module, not the crate root.
    pub file_of_mod: HashMap<RelPath, EntityId>,
    /// Declaring file of a `mod foo;` entity (`src/lib.rs` for `mod outer;`).
    pub mod_decl_file: HashMap<EntityId, RelPath>,
    /// Parent `mod` of a nested `mod` (`outer` for `mod outer { mod inner; }`).
    pub mod_parent: HashMap<EntityId, EntityId>,
    /// Parent files for `super::` / `super::super::` out of a file module.
    pub super_files: Vec<RelPath>,
    /// Inside an inline `mod inner { }` (not only a file loaded by `mod foo;`).
    pub inline_mod: bool,
    /// Names brought in by `use` in this module. File-module isolation drops
    /// unique-crate lookup, so `use super::parse; parse()` must still bind.
    pub use_imports: HashMap<(String, Namespace), EntityId>,
    /// `use path::h as hh` — `hh` is a local spelling, not an Entity hole.
    pub use_aliases: HashSet<String>,
    /// `pub use` names visible as `crate::parse` / `crate::engine::foo`.
    pub file_reexports: HashMap<RelPath, HashMap<(String, Namespace), EntityId>>,
    /// File-level `use` / `use as` names, including private ones, so
    /// `super::foo::parse` after `use a as foo` in the parent file still binds.
    pub file_imports: HashMap<RelPath, HashMap<(String, Namespace), EntityId>>,
    /// `pub use` inside a `mod`, for `crate::engine::foo` after `pub use merge::foo`.
    pub mod_reexports: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// Private `use` / `use as` names inside a `mod`, so `super::foo::parse`
    /// after `mod outer { use a as foo; … }` still binds.
    pub mod_imports: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// When set, [`crate::engine::canon`] records pub uses into the reexport maps.
    pub bind_reexports: bool,
    /// Every `mod` entity, so `use a as b; b::parse` is a module path, not Type::name.
    pub mods: HashSet<EntityId>,
    /// `use a as b` / `pub use a as b` — `b` is a local spelling, not the entity's name.
    pub alias_spellings: HashSet<String>,
    /// `#[macro_export]` names. rustc injects them at the crate root, so a
    /// file module's nested-mod isolation still sees `parse!()`.
    pub macro_exports: Arc<HashMap<String, EntityId>>,
}

impl Env {
    pub fn lookup(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(id) = Self::lookup_in_map(Some(&self.nested_items), name, ns) {
            return Some(id);
        }
        if let Some(m) = self.self_mod {
            if let Some(id) = Self::lookup_in_map(self.mod_items.get(&m), name, ns) {
                return Some(id);
            }
        }
        if let Some(id) = Self::lookup_in_map(Some(&self.use_imports), name, ns) {
            return Some(id);
        }
        if self.use_aliases.contains(name) {
            return None;
        }
        if ns == Namespace::Value {
            if let Some(&id) = self.macro_exports.get(name) {
                return Some(id);
            }
        }
        if self.in_nested_mod {
            return None;
        }
        self.lookup_module(name, ns)
    }

    /// `super::f` (`depth` 1) / `super::super::f` (`depth` 2). Past the last
    /// nested parent module, this is the crate root.
    pub fn lookup_super(&self, name: &str, ns: Namespace, depth: usize) -> Option<EntityId> {
        if depth == 0 {
            return None;
        }
        let i = depth - 1;
        if let Some(map) = self.super_stack.get(i) {
            return Self::lookup_in_map(Some(map), name, ns);
        }
        let rest = i - self.super_stack.len();
        if self.inline_mod && rest == 0 {
            return self
                .current_file
                .as_ref()
                .and_then(|file| self.lookup_file(file, name, ns))
                .or_else(|| self.lookup_module(name, ns));
        }
        let file_i = if self.inline_mod { rest - 1 } else { rest };
        if let Some(file) = self.super_files.get(file_i) {
            return self.lookup_file(file, name, ns);
        }
        self.lookup_module(name, ns)
    }

    /// `crate::a::b` — `a` is crate-root, then each segment is a child of that mod.
    pub fn lookup_crate_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_crate_root(&segs[0], ns);
        }
        let start = self.lookup_crate_root(&segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `crate::parse` is the crate root, not a same-named item in this file module.
    fn lookup_crate_root(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(file) = self.super_files.last() {
            return self.lookup_file(file, name, ns);
        }
        if let Some(file) = &self.current_file {
            if let Some(id) = self.lookup_file(file, name, ns) {
                return Some(id);
            }
        }
        self.lookup_module(name, ns)
    }

    fn lookup_file(&self, file: &RelPath, name: &str, ns: Namespace) -> Option<EntityId> {
        Self::lookup_in_map(self.by_file.get(file), name, ns)
            .or_else(|| Self::lookup_in_map(self.file_reexports.get(file), name, ns))
            .or_else(|| Self::lookup_in_map(self.file_imports.get(file), name, ns))
    }

    /// `super::a::b` after `depth` `super::` prefixes.
    pub fn lookup_super_path(
        &self,
        depth: usize,
        segs: &[String],
        ns: Namespace,
    ) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_super(&segs[0], ns, depth);
        }
        let start = self.lookup_super(&segs[0], Namespace::Type, depth)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `self::a::b` in the enclosing module.
    pub fn lookup_self_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        let start_mod = self.self_mod?;
        if segs.len() == 1 {
            return self.lookup_in_mod(start_mod, &segs[0], ns);
        }
        let start = self.lookup_in_mod(start_mod, &segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    fn lookup_in_mod(&self, m: EntityId, name: &str, ns: Namespace) -> Option<EntityId> {
        Self::lookup_in_map(self.mod_items.get(&m), name, ns)
            .or_else(|| Self::lookup_in_map(self.mod_reexports.get(&m), name, ns))
            .or_else(|| Self::lookup_in_map(self.mod_imports.get(&m), name, ns))
    }

    fn walk_mod_path(&self, start: EntityId, rest: &[String], ns: Namespace) -> Option<EntityId> {
        if rest.is_empty() {
            return Some(start);
        }
        let mut id = start;
        for s in &rest[..rest.len() - 1] {
            id = self.lookup_in_mod(id, s, Namespace::Type)?;
        }
        self.lookup_in_mod(id, rest.last()?, ns)
    }

    /// `use a as b; b::parse` — `b` names a module, then walk its children.
    /// A `pub use a as b` at the crate root is visible from a file module even
    /// though nested-mod isolation hides it from [`Self::lookup`].
    pub fn lookup_aliased_mod_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.len() < 2 {
            return None;
        }
        let start = self
            .lookup(&segs[0], Namespace::Type)
            .or_else(|| self.lookup_crate_path(&segs[..1], Namespace::Type))?;
        if !self.mods.contains(&start) {
            return None;
        }
        self.walk_mod_path(start, &segs[1..], ns)
    }

    pub fn is_mod(&self, id: EntityId) -> bool {
        self.mods.contains(&id)
    }

    /// File / crate / repo names, skipping nested-mod isolation. `crate::f`
    /// inside `mod inner` still binds the crate-root item.
    pub fn lookup_module(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(file) = &self.current_file {
            if let Some(id) = Self::lookup_in_map(self.by_file.get(file), name, ns) {
                return Some(id);
            }
            if let Some(krate) = crate_key(file) {
                if !self
                    .crate_ambiguous
                    .get(krate)
                    .is_some_and(|s| Self::is_ambiguous(s, name, ns))
                {
                    if let Some(id) = Self::lookup_in_map(self.by_crate.get(krate), name, ns) {
                        return Some(id);
                    }
                }
            }
        }
        self.lookup_global(name, ns)
    }

    pub fn lookup_global(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if Self::is_ambiguous(&self.names_ambiguous, name, ns) {
            return None;
        }
        Self::lookup_in_map(Some(self.names.as_ref()), name, ns)
    }

    fn is_ambiguous(set: &HashSet<(String, Namespace)>, name: &str, ns: Namespace) -> bool {
        set.contains(&(name.to_string(), ns))
            || set.contains(&(name.to_string(), Namespace::Any))
    }

    fn lookup_in_map(
        map: Option<&HashMap<(String, Namespace), EntityId>>,
        name: &str,
        ns: Namespace,
    ) -> Option<EntityId> {
        let map = map?;
        map.get(&(name.to_string(), ns))
            .copied()
            .or_else(|| map.get(&(name.to_string(), Namespace::Any)).copied())
    }

    pub fn insert(&mut self, name: impl Into<String>, ns: Namespace, id: EntityId) {
        self.insert_ranked(name, ns, id, false);
    }

    fn insert_ranked(
        &mut self,
        name: impl Into<String>,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let name = name.into();
        Self::occupy(
            Arc::make_mut(&mut self.names),
            Arc::make_mut(&mut self.names_ambiguous),
            Arc::make_mut(&mut self.primary),
            &name,
            ns,
            id,
            primary,
        );
    }

    /// Two primaries (`fn parse` in two files) or two secondaries are
    /// ambiguous. A primary may replace a secondary (`fn Foo` after
    /// `struct Foo`) without last-wins Free — they share a spelling, not a
    /// namespace.
    fn occupy(
        map: &mut HashMap<(String, Namespace), EntityId>,
        amb: &mut HashSet<(String, Namespace)>,
        primaries: &mut HashSet<(String, Namespace)>,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let key = (name.to_string(), ns);
        if let Some(old) = map.get(&key) {
            if *old != id {
                let old_primary = primaries.contains(&key);
                if old_primary && !primary {
                    return;
                }
                if old_primary == primary {
                    amb.insert(key.clone());
                }
            }
        }
        map.insert(key.clone(), id);
        if primary {
            primaries.insert(key);
        }
    }

    pub fn export_macro(&mut self, name: impl Into<String>, id: EntityId) {
        Arc::make_mut(&mut self.macro_exports).insert(name.into(), id);
    }

    pub fn insert_def(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        self.insert_def_in(name, kind, id, None);
    }

    pub fn insert_def_in(
        &mut self,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
        file: Option<&RelPath>,
    ) {
        let name = name.into();
        if kind == Kind::Mod {
            self.mods.insert(id);
        }
        for ns in namespaces_for(kind) {
            if *ns == Namespace::Value
                && !is_value_primary(kind)
                && self.lookup_global(&name, Namespace::Value).is_some()
            {
                continue;
            }
            let primary = is_value_primary(kind) && *ns == Namespace::Value;
            self.insert_ranked(&name, *ns, id, primary);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), *ns), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, *ns, id, primary);
                }
            }
        }
        if is_value_primary(kind) {
            self.insert_ranked(&name, Namespace::Value, id, true);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), Namespace::Value), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, Namespace::Value, id, true);
                }
            }
        }
    }

    fn insert_crate(
        &mut self,
        krate: &str,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        Self::occupy(
            Arc::make_mut(&mut self.by_crate)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_ambiguous)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_primary)
                .entry(krate.to_string())
                .or_default(),
            name,
            ns,
            id,
            primary,
        );
    }

    pub fn insert_defs(&mut self, defs: &[(&str, Kind, EntityId)]) {
        for (name, kind, id) in defs {
            self.insert_def(*name, *kind, *id);
        }
    }

    /// Bind a nested item for the duration of one `resolve`. Last insert wins
    /// so an inner function's helper shadows one on an enclosing function.
    pub fn insert_nested(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            self.nested_items.insert((name.clone(), *ns), id);
        }
    }

    pub fn insert_mod_child(
        &mut self,
        parent: EntityId,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        self.mods.insert(parent);
        if kind == Kind::Mod {
            self.mods.insert(id);
            self.mod_parent.insert(id, parent);
        }
        let map = self.mod_items.entry(parent).or_default();
        Self::insert_super_level(map, name, kind, id);
    }

    pub fn insert_super_level(
        map: &mut HashMap<(String, Namespace), EntityId>,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            map.insert((name.clone(), *ns), id);
        }
    }
}

pub fn namespaces_for(kind: Kind) -> &'static [Namespace] {
    match kind {
        Kind::Fn | Kind::Const | Kind::Static | Kind::Macro => &[Namespace::Value],
        Kind::Struct | Kind::Enum => &[Namespace::Type, Namespace::Value],
        Kind::Union | Kind::Trait | Kind::TypeAlias => &[Namespace::Type],
        Kind::Mod => &[Namespace::Value, Namespace::Type],
        Kind::Impl | Kind::Opaque | Kind::JsStaticBlock => &[],
        Kind::JsFunction
        | Kind::JsClass
        | Kind::JsMethod
        | Kind::JsGetter
        | Kind::JsSetter
        | Kind::JsField
        | Kind::JsStaticMethod
        | Kind::JsStaticField
        | Kind::JsDeclarator => &[Namespace::Value],
    }
}

fn is_value_primary(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Fn
            | Kind::Const
            | Kind::Static
            | Kind::Macro
            | Kind::JsFunction
            | Kind::JsClass
            | Kind::JsMethod
            | Kind::JsGetter
            | Kind::JsSetter
            | Kind::JsField
            | Kind::JsStaticMethod
            | Kind::JsStaticField
            | Kind::JsDeclarator
    )
}

/// `crates/svc-core/src/ids.rs` → `svc-core`. Paths outside `crates/` have no crate key.
fn crate_key(file: &RelPath) -> Option<&str> {
    file.as_str()
        .strip_prefix("crates/")
        .and_then(|rest| rest.split('/').next())
        .filter(|s| !s.is_empty())
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct EntityKindRule {
    pub node_kind: &'static str,
    pub kind: Kind,
    pub name_field: Option<&'static str>,
    pub body_field: Option<&'static str>,
    pub children_field: Option<&'static str>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Locator {
    Itself,
    Field(&'static str),
    ChildIndex(usize),
    FieldWithKind(&'static str, &'static str),
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Visibility {
    Whole,
    AfterStmt,
    /// Fields resolve against the binder's own parent, not the scope node.
    Sub(&'static [&'static str]),
    Hoisted,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BinderClass {
    Local,
    Generic,
    Label,
    Item,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum When {
    Always,
    ThroughBlock,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Barrier {
    pub ns: Namespace,
    pub class: BinderClass,
    pub when: When,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Role {
    Binder {
        namespace: Namespace,
        visibility: Visibility,
        locator: Locator,
    },
    Reference {
        namespace: Namespace,
    },
    Scope {
        opens: &'static [Namespace],
        barriers: &'static [Barrier],
    },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct CommutativeRule {
    pub parent: Option<Kind>,
    pub only_child_kinds: Option<&'static [Kind]>,
    pub except_child_kinds: Option<&'static [Kind]>,
}

pub trait Lang: Send + Sync {
    fn language(&self) -> tree_sitter::Language;
    fn name(&self) -> &'static str;
    fn extensions(&self) -> &'static [&'static str];
    fn entity_kinds(&self) -> &'static [EntityKindRule];
    fn entity_name(&self, node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String>;
    fn roles(
        &self,
        node: tree_sitter::Node<'_>,
        field: Option<&str>,
        src: &[u8],
        env: &Env,
    ) -> Vec<Role>;
    fn opaque_nodes(&self) -> &'static [&'static str];
    fn commutative_parents(&self) -> &'static [CommutativeRule];
    fn trivia_kinds(&self) -> &'static [&'static str];
    /// Text to wrap a lone member in so it parses, when a definition is added to or edited
    /// under a parent of `parent` kind: a JS method is not a program on its own, a Rust
    /// impl method is an item. `None` means the member parses standalone.
    fn member_shell(&self, _parent: Kind) -> Option<(&'static str, &'static str)> {
        None
    }

    /// Leaf node kinds whose text is a literal (numbers, strings, chars, booleans);
    /// canonicalisation keeps their text as `Token::Lit`.
    fn literal_kinds(&self) -> &'static [&'static str] {
        &[]
    }
    /// Override the table kind for nodes that share a grammar kind (JS getters/setters).
    fn refine_kind(&self, _node: tree_sitter::Node<'_>, _src: &[u8]) -> Option<Kind> {
        None
    }
}

pub struct Langs {
    langs: Vec<Box<dyn Lang>>,
}

impl Langs {
    pub fn new(langs: Vec<Box<dyn Lang>>) -> Self {
        Self { langs }
    }

    pub fn for_path(&self, p: &RelPath) -> Option<&dyn Lang> {
        let ext = p.extension()?;
        self.langs
            .iter()
            .find(|l| l.extensions().iter().any(|e| *e == ext))
            .map(|b| &**b)
    }

    pub fn iter(&self) -> impl Iterator<Item = &dyn Lang> {
        self.langs.iter().map(|b| &**b)
    }
}

#[derive(Clone, Debug)]
pub struct RawEntity {
    pub kind: Kind,
    pub name: String,
    pub name_range: Option<ByteRange>,
    pub item_range: ByteRange,
    pub bytes_range: ByteRange,
    pub parent_idx: Option<usize>,
    pub children: Vec<usize>,
    /// `#[path = "bar.rs"]` on `mod foo;` — the file that is this module.
    pub path_attr: Option<String>,
    /// `#[macro_export]` — rustc puts the macro at the crate root even when
    /// the definition sits in a nested module.
    pub macro_export: bool,
    /// `#[macro_use]` on `mod fs` — rustc injects that module's macros at the
    /// crate root, like `#[macro_export]` on each of them.
    pub macro_use: bool,
    /// `#[macro_use(parse, other)]` — only these names. `None` with `macro_use`
    /// means every macro in the module.
    pub macro_use_only: Option<Vec<String>>,
    /// `include!("foo.rs")` paths inside this `mod`, relative to the declaring file.
    pub include_paths: Vec<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Resolution {
    pub slots: Vec<(ByteRange, crate::ids::Slot, Namespace)>,
    pub refs: Vec<(ByteRange, crate::content::IdentRef)>,
}

crates/svc-core/tests/o3_rename.rs.Text:
use std::collections::BTreeMap;

use svc_core::engine::{
    add_def, edit_def, ingest_file, lookup_name, redefine, rename, render, rust_langs,
    snapshot_files, status_report,
};
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::store::MemStore;
use svc_core::{IdentRef, Intent, RustLang, Store, Token};

const SRC: &str = r#"fn parse(s: &str) -> usize { s.len() }
fn load(path: &str) -> usize { parse(path) }
"#;

#[test]
fn o3_rename_does_not_touch_other_hashes() {
    let store = MemStore::new();
    let lang = RustLang;
    let path = RelPath::new("src/lib.rs").unwrap();
    let snap = ingest_file(SRC.as_bytes(), path, &lang, &store, ChangeId::new()).unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let load_before = snap.entities[&load_id].clone();
    let parse_before = snap.entities[&parse_id].clone();

    let next = rename(&store, &snap, parse_id, "parse_config").unwrap();
    let load_after = &next.entities[&load_id];
    let parse_after = &next.entities[&parse_id];

    assert_eq!(parse_after.name, "parse_config");
    assert_eq!(parse_after.content, parse_before.content);
    assert_eq!(parse_after.bytes, parse_before.bytes);
    assert_eq!(load_after.content, load_before.content);
    assert_eq!(load_after.bytes, load_before.bytes);

    let langs = rust_langs();
    let rendered = render(&next, &store, &langs, false).unwrap();
    let text = String::from_utf8(rendered.files.values().next().unwrap().clone()).unwrap();
    assert!(text.contains("fn parse_config"), "{text}");
    assert!(text.contains("parse_config(path)"), "{text}");
    assert!(!text.contains("fn parse("), "{text}");
}

#[test]
fn snapshot_files_matches_ingest_and_status_is_clean() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    assert!(snap.entities.values().any(|e| e.name == "parse"));
    assert!(snap.entities.values().any(|e| e.name == "load"));
    let again = snapshot_files(&store, &langs, &files, Some(&snap), change).unwrap();
    let report = status_report(&store, &snap, &again).unwrap();
    assert_eq!(
        report.summary(),
        format!("{} entities, 0 changes", snap.entities.len())
    );
}

#[test]
fn redefine_keeps_callees_as_entity_holes() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let text = b"fn load(path: &str) -> usize { parse(path) + 1 }\n";
    let (_, content, bytes) = redefine(&store, &langs, &snap, load_id, text).unwrap();
    let c = store.get_content(content).unwrap();
    assert!(
        c.tokens.iter().any(|t| match t {
            Token::Ident(IdentRef::Entity(id)) => *id == parse_id,
            _ => false,
        }),
        "callee must resolve to parse's entity id, got {:?}",
        c.tokens
    );
    let _ = bytes;
}

#[test]
fn layout_local_rename_is_not_semantic() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    let edited = SRC.replace(
        "fn parse(s: &str) -> usize { s.len() }",
        "fn parse(input: &str) -> usize { input.len() }",
    );
    files.insert(path, edited.into_bytes());
    let next = snapshot_files(&store, &langs, &files, Some(&snap), change).unwrap();
    let report = status_report(&store, &snap, &next).unwrap();
    assert_eq!(report.semantic, 0, "{:?}", report.deltas);
    assert_eq!(report.layout, 1, "{:?}", report.deltas);
}

#[test]
fn redefine_without_trailing_newline_keeps_callee_entity() {
