    let content = store.get_content(next.entities[&load].content).unwrap();
    let hits = content
        .tokens
        .iter()
        .filter(|t| matches!(t, Token::Ident(IdentRef::Entity(id)) if *id == method))
        .count();
    assert_eq!(
        hits, 2,
        "edit-def must keep same-impl calls as entity holes, got {:?}",
        content.tokens
    );
}

